struct Pressure {
 vector<double> floor,roof,width,length,slot,water,load,start,incoming,outgoing,external,history,transfers,edgeDistance,edgeLoss,forward,reverse;
 vector<size_t> owner,ea;vector<int> eb;double friction=.03,gravity=9.81,multiplier=1,maxResidual=0;size_t donorLimited=0,maxIterations=0;double maxFluxChange=0;
 void init(napi_env env,napi_value in,size_t np,int owners){floor=array(env,in,"pressureFloor");roof=array(env,in,"pressureRoof");width=array(env,in,"pressureWidth");length=array(env,in,"pressureLength");water=array(env,in,"pressureWater");load=array(env,in,"pressureLoad");slot=array(env,in,"pressureSlotArea");auto own=array(env,in,"pressureOwner"),a=array(env,in,"pressureEdgeA"),b=array(env,in,"pressureEdgeB");edgeDistance=array(env,in,"pressureEdgeDistance");edgeLoss=array(env,in,"pressureEdgeLoss");size_t n=floor.size();need(n>0&&roof.size()==n&&width.size()==n&&length.size()==n&&water.size()==n&&slot.size()==n&&own.size()==n&&load.size()==n*12,"Invalid pressure compartments");for(size_t i=0;i<n;i++){need(std::isfinite(floor[i])&&roof[i]>floor[i]&&width[i]>0&&length[i]>0&&slot[i]>0&&water[i]>=0&&std::isfinite(water[i])&&own[i]>=0&&own[i]<owners&&own[i]==std::floor(own[i]),"Invalid pressure geometry/state");owner.push_back(size_t(own[i]));}for(double v:load)need(v>=0&&std::isfinite(v),"Invalid pressure load");need(a.size()==b.size()&&a.size()==edgeDistance.size()&&a.size()==edgeLoss.size(),"Invalid pressure edges");for(size_t j=0;j<a.size();j++){need(a[j]>=0&&a[j]<n&&a[j]==std::floor(a[j])&&b[j]>=-double(np)&&b[j]<double(n)&&b[j]==std::floor(b[j])&&a[j]!=b[j]&&edgeDistance[j]>0&&edgeLoss[j]>=0,"Invalid pressure edge");ea.push_back(size_t(a[j]));eb.push_back(int(b[j]));if(b[j]>=0)need(owner[size_t(a[j])]==owner[size_t(b[j])],"Pressure owner mismatch");}auto p=prop(env,in,"pressureParameters");friction=number(env,p,"frictionFactor");gravity=number(env,p,"gravityMPerS2");multiplier=number(env,p,"exchangeMultiplier");need(friction>0&&gravity>0&&multiplier>=0&&multiplier<=1,"Invalid pressure parameters");start=water;incoming.assign(n,0);outgoing.assign(n,0);external.assign(n,0);forward.assign(a.size(),0);reverse.assign(a.size(),0);}
 double head(size_t i,double v)const{double cap=width[i]*length[i]*(roof[i]-floor[i]);return v<=cap?floor[i]+v/(width[i]*length[i]):roof[i]+(v-cap)/slot[i];}
 double discharge(size_t e,double ha,double hb)const{size_t a=ea[e];int b=eb[e];double crest=floor[a],w=width[a],height=roof[a]-floor[a];if(b>=0){crest=std::max(crest,floor[b]);w=std::min(w,width[b]);height=std::min(height,roof[b]-floor[b]);}double delta=ha-hb,wet=std::min(height,std::max(0.,std::max(ha,hb)-crest)),area=w*wet,dh=2*w*height/(w+height);if(delta==0||area==0)return 0;return std::copysign(multiplier*area*std::sqrt(2*gravity*std::abs(delta)/(friction*edgeDistance[e]/dh+edgeLoss[e])),delta);}
 void reset(){start=water;std::fill(incoming.begin(),incoming.end(),0);std::fill(outgoing.begin(),outgoing.end(),0);std::fill(external.begin(),external.end(),0);std::fill(forward.begin(),forward.end(),0);std::fill(reverse.begin(),reverse.end(),0);}
 void step(int phase,int steps,double dt,const vector<Curve>& curves,vector<double>& ponds,vector<double>& row,size_t nf,const vector<double>& nodeOwner){for(size_t i=0;i<water.size();i++){double v=load[i*12+phase]/steps;water[i]+=v;external[i]+=v;row[owner[i]*nf+1]+=v;}vector<double> qprev(ea.size(),0);bool converged=false;for(size_t iteration=0;iteration<2000;iteration++){double change=0,scale=1;for(size_t e=0;e<ea.size();e++){size_t a=ea[e];int b=eb[e];size_t p=b<0?size_t(-b-1):0;if(b<0)need(size_t(nodeOwner[p])==owner[a],"Pressure endpoint owner mismatch");double va=water[a]+qprev[e],vb=(b>=0?water[b]:ponds[p])-qprev[e];auto otherHead=[&](double v){return b>=0?head(size_t(b),v):curves[p].level(v);};auto residual=[&](double q){return q-dt*discharge(e,head(a,va-q),otherHead(vb+q));};double lo=-vb,hi=va,q;if(lo<=0&&hi>=0&&residual(0)==0){q=0;}else if(residual(lo)>=0){q=lo;}else if(residual(hi)<=0){q=hi;}else{for(int it=0;it<80;it++){double mid=lo+(hi-lo)/2;if(residual(mid)>0)hi=mid;else lo=mid;}q=lo+(hi-lo)/2;}water[a]=std::max(0.,va-q);if(b>=0)water[b]=std::max(0.,vb+q);else ponds[p]=std::max(0.,vb+q);change=std::max(change,std::abs(q-qprev[e]));scale=std::max(scale,std::abs(q));qprev[e]=q;}maxIterations=std::max(maxIterations,iteration+1);if(change<=std::max(1e-6,scale*2e-13)){maxFluxChange=std::max(maxFluxChange,change);converged=true;break;}}need(converged,"Pressure network failed to converge");for(size_t e=0;e<ea.size();e++){size_t a=ea[e];int b=eb[e];double q=qprev[e];if(q>=0){outgoing[a]+=q;if(b>=0)incoming[b]+=q;forward[e]+=q;}else{incoming[a]-=q;if(b>=0)outgoing[b]-=q;reverse[e]-=q;}}}

 void snapshot(){for(size_t i=0;i<water.size();i++){double residual=start[i]+external[i]+incoming[i]-outgoing[i]-water[i],relative=std::abs(residual)/std::max(1.,start[i]+external[i]+incoming[i]);maxResidual=std::max(maxResidual,relative);need(relative<2e-10,"Pressure water balance failure");for(double x:{start[i],water[i],external[i],incoming[i],outgoing[i],head(i,water[i])})history.push_back(x);}for(size_t j=0;j<ea.size();j++){transfers.push_back(forward[j]);transfers.push_back(reverse[j]);}}
 void output(napi_env env,napi_value out){put(env,out,"pressureWater",water);put(env,out,"pressureHistory",history);put(env,out,"pressureTransfers",transfers);putnum(env,out,"maximumPressureWaterRelativeResidual",maxResidual);putnum(env,out,"maximumPressureIterations",maxIterations);putnum(env,out,"maximumPressureFinalFluxChangeM3",maxFluxChange);}
};
